def hidden_rule_fn(state):
    n = len(state)
    # n is the index where the new element will be appended
    def is_prime(k):
        if k < 2:
            return False
        for i in range(2, int(k**0.5) + 1):
            if k % i == 0:
                return False
        return True

    a = state[-2]
    b = state[-1]

    if is_prime(n):
        # ploon-XOR: bitwise XOR of two kreels, then mod 7
        new_val = (a ^ b) % 7
    else:
        # grolp-sum: arithmetic sum of two kreels plus 3, then mod 7
        new_val = (a + b + 3) % 7

    return state + [new_val]
